import Foundation
var checks = 0
func check(_ value: @autoclosure () -> Bool,_ title:String) { guard value() else { fatalError("FAIL: "+title) }; checks += 1; print("PASS: "+title) }
let start = Calendar.current.startOfDay(for:Date()), end = start.addingTimeInterval(3600)
var mixed = BatteryHour(start:start,end:end,sleepHours:0.5,activeKcal:0,heartRate:95,heartRateCount:8,heartRateCoverageHours:0.5)
var status = BatteryModel.calculate(hours:[mixed],anchor:50,baselineHR:55,now:end)
check(status.points.last!.effect!.awakeDrain == 0,"legacy sleeping coverage cannot establish awake drain")
check(status.points.last!.effect!.heartRateDrain == 0,"sleeping HR cannot establish awake strain")
check(status.points.last!.effect!.restRecharge == 0,"sleeping readings cannot establish awake rest")
mixed.awakeHeartRate = 100; mixed.awakeHeartRateCount = 8; mixed.awakeHeartRateCoverageHours = 0.25
status = BatteryModel.calculate(hours:[mixed],anchor:50,baselineHR:55,now:end)
check(abs(status.points.last!.effect!.awakeDrain-0.275) < 0.0001,"awake duration counted only for explicit coverage")
check(status.points.last!.effect!.heartRateDrain > 0,"actual awake elevated HR remains a signal")
let sleep = BatteryHour(start:start,end:end,sleepHours:1,activeKcal:0,heartRate:nil,heartRateCount:0)
let charged = BatteryModel.calculate(hours:[sleep],anchor:50,baselineHR:55,now:end)
let report = EnergyInsights.day(points:charged.points,day:start,now:end)
check(report.coveredSeconds == 3600,"first recorded bin contributes to chart coverage")
check(abs(report.charged-Double(charged.charged)) < 0.5,"first bin graph agrees with rounded status totals")
check(report.balance != nil && abs(report.balance!.residual) < 0.0001,"saved factors reconcile with curve")
let training = BatteryHour(start:start,end:end,sleepHours:0,activeKcal:nil,heartRate:nil,heartRateCount:0,workoutHours:1)
let trained = BatteryModel.calculate(hours:[training],anchor:50,baselineHR:nil,now:end)
check(trained.value != nil && trained.drained == 1,"workout-only input retains recorded duration")
check(trained.points.last!.effect!.activityDrain == 0,"workout-only input does not invent calories")
let floor = BatteryModel.calculate(hours:[BatteryHour(start:start,end:end,sleepHours:0,activeKcal:2000,heartRate:nil,heartRateCount:0)],anchor:6,baselineHR:nil,now:end)
let floorReport = EnergyInsights.day(points:floor.points,day:start,now:end)
check(floor.value == 5,"lower reserve boundary preserved")
check((floor.points.last!.effect!.boundaryAdjustment ?? 0) > 0,"clipping contribution saved")
check(floorReport.balance != nil && abs(floorReport.balance!.end-5) < 0.0001,"floor waterfall reconciles")
var unknown = training; unknown.workoutHours = nil
let resumed = BatteryModel.calculate(hours:[unknown,BatteryHour(start:end,end:end.addingTimeInterval(3600),sleepHours:1,activeKcal:0,heartRate:nil,heartRateCount:0)],anchor:50,baselineHR:nil,now:end.addingTimeInterval(3600))
let resumedReport = EnergyInsights.day(points:resumed.points,day:start,now:end.addingTimeInterval(3600))
check(resumedReport.coveredSeconds == 3600,"resume after unknown interval counts only observed bin")
let gapSleep = BatteryHour(start:end.addingTimeInterval(3600),end:end.addingTimeInterval(7200),sleepHours:1,activeKcal:0,heartRate:nil,heartRateCount:0)
let gapped = BatteryModel.calculate(hours:[sleep,gapSleep],anchor:50,baselineHR:nil,now:gapSleep.end)
let gapReport = EnergyInsights.day(points:gapped.points,day:start,now:gapSleep.end)
check(gapReport.coveredSeconds == 7200,"implicit missing gap never joins the curve")
check(gapReport.balance == nil,"disconnected intervals cannot produce endpoint waterfall")
var lowHRV = sleep; lowHRV.sleepHRVZ = -2; lowHRV.sleepHRVCount = 4
check(BatteryModel.calculate(hours:[lowHRV],anchor:50,baselineHR:nil,now:end).value! < charged.value!,"observed low sleeping HRV reduces recharge")
var highHRV = sleep; highHRV.sleepHRVZ = 1; highHRV.sleepHRVCount = 4
check(BatteryModel.calculate(hours:[highHRV],anchor:50,baselineHR:nil,now:end).points.last!.value! > charged.points.last!.value!,"comparable sleeping HRV can increase recharge")
var missingHRV = sleep; missingHRV.sleepHRVCount = 0
check(BatteryModel.calculate(hours:[missingHRV],anchor:50,baselineHR:nil,now:end).value == charged.value,"missing HRV is neutral, not low HRV")
let night = NightRecord(date:start,sleepHours:5,hrv:50,heartRate:55,hrvCount:4,heartRateCount:20)
let days = (0..<20).map { offset -> RecoveryDay in var n = night; n.date = start.addingTimeInterval(Double(offset-19)*86400); return RecoveryDay(night:n,activeKcal:0,sleepMidpointHour:nil) }
check(RecoveryModelV2.calculate(days:days,sleepTarget:4).last!.score! > RecoveryModelV2.calculate(days:days,sleepTarget:6).last!.score!,"configured goals below six hours use the same target as UI")
check(RecoveryModelV2.calculate(days:days,sleepTarget:12).last!.sleepGap > RecoveryModelV2.calculate(days:days,sleepTarget:10).last!.sleepGap,"configured goals above ten hours are not silently capped")
var loadDays = days; loadDays[19].activeKcal = 800
check(RecoveryModelV2.calculate(days:loadDays).last!.reasons.contains { $0.name == "前日活动负荷" },"observed zero-energy days participate in baseline")
let decision = DecisionEngine.make(estimate:nil,status:trained,lastNight:night,todayKcal:nil,strain:20,sleepTarget:.nan,intent:"训练",now:end)
check(decision.level == .hold,"known high load can guide rest when readiness missing")
check(!decision.actions.last!.reason.contains("恢复偏低"),"high-load advice does not invent low recovery")
check(decision.actions[1].reason.contains("8 小时"),"nonfinite sleep goal is formatted safely with fallback")
let old = BatteryHourEffect(sleepRecharge:100,restRecharge:0,awakeDrain:0,activityDrain:0,heartRateDrain:0,hrvDrain:0,sleepHRVAdjustment:0)
let oldReport = EnergyInsights.day(points:[BatteryPoint(date:start,value:50,mode:"旧"),BatteryPoint(date:end,value:100,mode:"旧",effect:old)],day:start,now:end)
check(oldReport.balance == nil,"legacy unaccounted clipping cannot falsely pass reconciliation")
let encoded = try! JSONEncoder().encode(mixed)
check(try! JSONDecoder().decode(BatteryHour.self,from:encoded).awakeHeartRateCount == 8,"new context fields round-trip")
print("\(checks) audit regression checks passed. Synthetic cases; not personal physiological validation.")
let pairs = EnergyInsights.feelings([EnergyCheckIn(date:end,rating:4),EnergyCheckIn(date:end.addingTimeInterval(7200),rating:2)],points:charged.points,now:end.addingTimeInterval(7200))
check(pairs.count == 1 && pairs[0].rating == 4,"self-rating pairs only nearby preceding model result")
check(EnergyInsights.feelings([EnergyCheckIn(date:start.addingTimeInterval(1800),rating:4)],points:charged.points,now:end).isEmpty,"initial engineering anchor cannot act as a measured comparison")
check(EnergyInsights.feelings([EnergyCheckIn(date:end,rating:6)],points:charged.points,now:end).isEmpty,"invalid subjective rating excluded")
check(EnergyInsights.feelings([EnergyCheckIn(date:end.addingTimeInterval(1),rating:4)],points:charged.points,now:end).isEmpty,"future check-in excluded")
var gapPoints = charged.points;gapPoints.append(BatteryPoint(date:end.addingTimeInterval(60),value:nil,mode:"缺少采样"))
check(EnergyInsights.feelings([EnergyCheckIn(date:end.addingTimeInterval(120),rating:4)],points:gapPoints,now:end.addingTimeInterval(120)).isEmpty,"missing latest bin prevents stale pairing across the gap")
let sensitivity = BatteryLedger(baselineHR:55,hours:[sleep]).anchorSensitivity(now:end)!
check(sensitivity.low < sensitivity.high,"early estimate exposes dependence on starting prior")
let oldJSON = "{\"start\":0,\"end\":3600,\"sleepHours\":0,\"activeKcal\":0,\"heartRate\":60,\"heartRateCount\":8,\"heartRateCoverageHours\":0.2}"
check(try! JSONDecoder().decode(BatteryHour.self,from:oldJSON.data(using:.utf8)!).awakeHeartRateCount == nil,"legacy saved bins decode without new context fields")
print("\(checks) final audit regression checks passed")
